get_ticket_status.afterResponse:
var names = {2: 'OPEN', 3: 'PENDING', 4: 'RESOLVED', 5: 'CLOSED'};
var responder = response.responder_id;
return [{ticket_status: names[response.status] !== undefined ? names[response.status] : response.status, assigned_status: responder === null || responder === undefined ? 'NOTASSIGNED' : 'ASSIGNED', assigned_id: responder}];

get_contacts.beforeRequest:
var form = (text) => encodeURIComponent(String(text)).replace(/[!'()~]/g, (c) => '%' + c.charCodeAt(0).toString(16).toUpperCase()).replace(/%20/g, '+');
var query = [];
if (inputs.filter_type && inputs.filter_value) query.push(form(inputs.filter_type) + '=' + form(inputs.filter_value));
if (inputs.filter_status) query.push('state=' + form(inputs.filter_status));
if (Number(inputs.per_page || 0) != 0) query.push('per_page=' + form(inputs.per_page));
request.url = request.url + '?' + query.join('&');
return request;

get_all_tickets_by_status.beforeRequest:
var text = String(inputs.status_filter || '').trim();
var chosen = text.startsWith('[') ? JSON.parse(text) : [text];
var form = (value) => encodeURIComponent(value).replace(/[!'()~]/g, (c) => '%' + c.charCodeAt(0).toString(16).toUpperCase()).replace(/%20/g, '+');
request.url = request.url + '?query=' + form('"' + chosen.map((item) => String(item).replace(/,/g, ' OR ')).join(' OR ') + '"');
return request;

get_all_tickets_by_status.afterResponse:
var names = {2: 'Open', 3: 'Pending', 4: 'Resolved', 5: 'Closed'};
var results = response.results.slice();
results.sort((a, b) => a.requester_id - b.requester_id);
return results.map((ticket) => ({id: ticket.id, requester_id: ticket.requester_id, responder_id: ticket.responder_id, company_id: ticket.company_id, status: names[ticket.status] || 'Unknown', subject: ticket.subject, created_at: ticket.created_at, updated_at: ticket.updated_at, description_text: ticket.description_text, description: ticket.description}));
